commands.command:
& 'C:\Program Files\Blender Foundation\Blender 4.2\blender.exe' --help | Select-String -Pattern 'online' -Context 1,2
$tempRoot = [IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\')
$targets = @(Get-ChildItem -LiteralPath $tempRoot -Directory -Filter 'kai_release_063_*' | Where-Object { $_.CreationTime -gt (Get-Date).AddHours(-1) })
foreach ($target in $targets) {
  $resolved = (Resolve-Path -LiteralPath $target.FullName).Path
  if (-not $resolved.StartsWith($tempRoot + '\') -or [IO.Path]::GetFileName($resolved) -notlike 'kai_release_063_*') { throw "Refusing cleanup outside QA temp: $resolved" }
  "REMOVING_QA_TEMP=$resolved"
  Remove-Item -LiteralPath $resolved -Recurse -Force
}

$qaRoot = Join-Path ([IO.Path]::GetTempPath()) ('kai_phase1_2_build_' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $qaRoot | Out-Null
try {
  & 'C:\Program Files\Blender Foundation\Blender 5.1\blender.exe' --factory-startup --command extension build --source-dir 'D:\dev-blender-addon\mixamo-rig-kai' --output-dir $qaRoot
  if ($LASTEXITCODE -ne 0) { throw 'Extension build failed' }
  $zipPath = (Resolve-Path -LiteralPath (Join-Path $qaRoot 'mixamo_rig_kai-0.6.3.zip')).Path
  Add-Type -AssemblyName System.IO.Compression.FileSystem
  $archive = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
  try {
    $names = @($archive.Entries | ForEach-Object FullName)
    $manifest = $archive.Entries | Where-Object FullName -eq 'blender_manifest.toml'
    $reader = [IO.StreamReader]::new($manifest.Open()); $manifestText = $reader.ReadToEnd(); $reader.Dispose()
    $prohibited = @($names | Where-Object { $_ -match '(^|/)(tools|analysis|reports|__pycache__)(/|$)' -or $_ -eq 'AGENTS.md' -or $_ -match '\.(pyc|pyo|log)$' })
    "BUILD_FILE=$zipPath"
    "BUILD_ENTRIES=$($names.Count)"
    "BUILD_HAS_FACIAL=$($names -contains 'kai_facial.py')"
    "BUILD_VERSION_063=$($manifestText -match 'version = "0\.6\.3"')"
    "BUILD_PROHIBITED_COUNT=$($prohibited.Count)"
    Get-Item -LiteralPath $zipPath | ForEach-Object { "BUILD_SIZE=$($_.Length)" }
    Get-FileHash -LiteralPath $zipPath -Algorithm SHA256 | ForEach-Object { "BUILD_SHA256=$($_.Hash)" }
  } finally { $archive.Dispose() }
} finally {
  if (Test-Path -LiteralPath $qaRoot) {
    $resolved = (Resolve-Path -LiteralPath $qaRoot).Path
    $tempRoot = [IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\')
    if (-not $resolved.StartsWith($tempRoot + '\') -or [IO.Path]::GetFileName($resolved) -notlike 'kai_phase1_2_build_*') { throw "Refusing cleanup outside build temp: $resolved" }
    Remove-Item -LiteralPath $resolved -Recurse -Force
  }
}
$official = 'D:\dev-blender-addon\mixamo-rig-kai\mixamo_rig_kai-0.6.3.zip'
if (Test-Path -LiteralPath $official) { Get-FileHash -LiteralPath $official -Algorithm SHA256 | ForEach-Object { "OFFICIAL_RELEASE_SHA256_UNCHANGED=$($_.Hash)" } }

